import zipfile,csv,io,json,pathlib,sys
root=pathlib.Path('.')
z=zipfile.ZipFile(sys.argv[1]); prefix=z.namelist()[0]
def rows(name): return csv.DictReader(io.TextIOWrapper(z.open(prefix+name+'.csv'),encoding='utf-8-sig'))
mapping={168878:('熟白米饭',['米饭'], '碗',150),169097:('橙子',['橙'], '个',130),170379:('生西兰花',[], '克',1),170393:('生胡萝卜',[], '克',1),170440:('水煮土豆',[], '克',1),170457:('番茄',['西红柿'], '个',150),171265:('全脂牛奶',[], '毫升',1.03),173424:('水煮蛋',['煮鸡蛋','煮鸡蛋'], '个',50),173904:('干燕麦片',['干燕麦'], '克',1),173905:('燕麦粥',['熟燕麦','煮燕麦'], '碗',250),173944:('香蕉',[], '根',100)}
mapping.update({
167762:('草莓',[], '克',1),167765:('西瓜',[], '克',1),168153:('猕猴桃',['奇异果'], '个',75),168409:('黄瓜',[], '克',1),168462:('生菠菜',[], '克',1),168484:('水煮红薯',[], '克',1),169118:('梨',[], '个',180),169124:('菠萝',[], '克',1),169249:('生菜',[], '克',1),169251:('生白蘑菇',[], '克',1),169910:('芒果',[], '克',1),169928:('桃子',[], '个',150),169975:('生卷心菜',[], '克',1),169986:('生花菜',[], '克',1),170187:('核桃仁',[], '克',1),170567:('原味杏仁',[], '克',1),171284:('原味全脂酸奶',[], '克',1),171287:('生鸡蛋',[], '个',50),171477:('烤鸡胸肉',[], '克',1),171688:('苹果',[], '个',180),172421:('水煮扁豆',[], '克',1),172430:('生花生仁',[], '克',1),172475:('石膏老豆腐',[], '克',1),172688:('全麦面包',[], '片',30),174270:('干黄豆',[], '克',1),174683:('葡萄',[], '克',1),175168:('熟三文鱼',[], '克',1)
})

foods={int(r['fdc_id']):r['description'] for r in rows('food') if int(r['fdc_id']) in mapping}
ns={i:{} for i in mapping}; fields={'1008':'kcal','1003':'protein','1005':'carb','1004':'fat','1079':'fiber','2000':'sugar','1093':'sodium'}
for r in rows('food_nutrient'):
 i=int(r['fdc_id']); k=fields.get(r['nutrient_id'])
 if i in ns and k: ns[i][k]=float(r['amount'])
out=[]
for i,(name,aliases,unit,grams) in mapping.items(): out.append(dict(name=name,aliases=aliases,unit=unit,grams=grams,fdcId=i,description=foods[i],per100g={k:ns[i].get(k) for k in fields.values()}))
(root/'utils/nutrition-data.js').write_text('// USDA SR Legacy 2018, CC0; generated by scripts/build-nutrition-data.py\nmodule.exports = '+json.dumps(out,ensure_ascii=False,separators=(',',':'))+';\n',encoding='utf-8')
